      'Роль OLAN в проектах партнёров': 'OLAN\'s role in partner projects',
      'Заполните имя, email и телефон.': 'Please fill in your name, email and phone.',
      'Наши комплексы для этого решения': 'Our systems for this solution',
      'Услуги и направления деятельности': 'Services and areas of work',
