      zh: 'PARKING可记录在禁停区域停车、临时停车及其他违法行为，识别车辆并将附带照片和视频的事件即时上传至服务器。模块支持全高清与4K拍摄，可两种方式工作：独立部署于移动执法点或固定卡口，或作为大型系统的一部分接入数据处理中心。照片与视频档案保存每一起事件。',
