          zh: '研发中心同时覆盖三个层面：计算机视觉、应用软件与电子技术。车牌与违法识别算法均为自研，并基于本地区真实道路数据训练。',
          ar: 'يغطي مركز التطوير ثلاث طبقات دفعة واحدة: الرؤية الحاسوبية والبرمجيات التطبيقية والإلكترونيات. وخوارزميات التعرّف على اللوحات والمخالفات ملكٌ لنا ومدرّبة على بيانات طرق حقيقية من المنطقة.',
          uk: 'Центр розробки закриває три шари одразу: комп\'ютерний зір, прикладне програмне забезпечення та електроніку. Алгоритми розпізнавання номерів і порушень — власні, навчені на реальних дорожніх даних регіону.',
