          ru: 'Здесь же пишется встроенное ПО комплексов: контроль целостности при каждой загрузке, локальная база данных без потерь при обрыве связи, трансляция по RTSP и единый HTTP-API для интеграции.',
          en: 'The embedded software for the systems is written here too: integrity checks at every boot, a local database that survives connection loss, RTSP streaming and a single HTTP API for integration.',
