          ar: 'هنا أيضًا تُكتب البرمجيات المدمجة للأنظمة: فحص السلامة عند كل إقلاع، وقاعدة بيانات محلية لا تفقد البيانات عند انقطاع الاتصال، وبث RTSP، وواجهة HTTP-API موحّدة للتكامل.',
