    icon: 'LayoutGrid',
    title: { ru: 'Единая интеграционная платформа', en: 'Unified integration platform', zh: '统一集成平台', ar: 'منصة التكامل الموحّدة', uz: 'Yagona integratsiya platformasi', uk: 'Єдина інтеграційна платформа' },
    subtitle: { ru: 'Городская платформа данных — в разработке', en: 'Urban data platform — in development', zh: '城市数据平台——开发中', ar: 'منصة بيانات المدينة — قيد التطوير', uz: 'Shahar ma\'lumotlar platformasi — ishlab chiqilmoqda', uk: 'Міська платформа даних — у розробці' },
    description: {
      ru: 'Единая интеграционная платформа собирает данные от любых городских источников — камер, комплексов фиксации, систем весогабаритного контроля, домофонов — и превращает их в понятную картину для управления городом. Платформа обрабатывает, анализирует и визуализирует данные, а подсистемы подключаются как модули: видеоплатформа с распознаванием лиц и контролем доступа, весогабаритный контроль, платные парковки, выявление инцидентов и мониторинг дорожной инфраструктуры с подсистемой ROADLY. Платформа находится в разработке.',
      en: 'The unified integration platform gathers data from any city source — cameras, enforcement systems, weigh-in-motion stations, intercoms — and turns it into a clear picture for managing the city. It processes, analyses and visualises the data, and subsystems plug in as modules: a video platform with face recognition and access control, weigh-in-motion control, paid parking, incident detection and road infrastructure monitoring with the ROADLY subsystem. The platform is currently in development.',
      uz: 'Yagona integratsiya platformasi istalgan shahar manbalaridan — kameralar, qayd etish majmualari, vazn-gabarit nazorati tizimlari, domofonlardan — maʼlumotlarni yigʻadi va ularni shaharni boshqarish uchun tushunarli manzaraga aylantiradi. Platforma maʼlumotlarni qayta ishlaydi, tahlil qiladi va vizuallashtiradi, quyi tizimlar esa modul sifatida ulanadi: yuzni aniqlash va kirish nazorati bilan videoplatforma, vazn-gabarit nazorati, pullik avtoturargohlar, hodisalarni aniqlash va ROADLY quyi tizimi bilan yoʻl infratuzilmasi monitoringi. Platforma ishlab chiqilmoqda.',
      uk: 'Єдина інтеграційна платформа збирає дані з будь-яких міських джерел — камер, комплексів фіксації, систем вагогабаритного контролю, домофонів — і перетворює їх на зрозумілу картину для керування містом. Платформа обробляє, аналізує та візуалізує дані, а підсистеми під’єднуються як модулі: відеоплатформа з розпізнаванням облич і контролем доступу, вагогабаритний контроль, платні паркування, виявлення інцидентів і моніторинг дорожньої інфраструктури з підсистемою ROADLY. Платформа перебуває в розробці.',
      zh: '统一集成平台汇集来自各类城市数据源的数据——摄像机、违法取证系统、称重超限检测系统、门禁对讲——并将其转化为清晰直观的城市管理全景。平台对数据进行处理、分析和可视化，各子系统以模块形式接入：具备人脸识别与门禁控制的视频平台、称重超限检测、收费停车、事件识别，以及搭载ROADLY子系统的道路基础设施监测。该平台目前正在开发中。',
      ar: 'تجمع المنصة الموحّدة للتكامل البيانات من أي مصدر في المدينة — الكاميرات وأنظمة رصد المخالفات وأنظمة مراقبة الأوزان والأبعاد وأنظمة الاتصال الداخلي — وتحوّلها إلى صورة واضحة لإدارة المدينة. تعالج المنصة البيانات وتحلّلها وتعرضها بصريًا، وتُربط الأنظمة الفرعية على شكل وحدات: منصة فيديو مع التعرّف على الوجوه والتحكم في الدخول، ومراقبة الأوزان والأبعاد، ومواقف السيارات المدفوعة، والكشف عن الحوادث، ومراقبة البنية التحتية للطرق عبر النظام الفرعي ROADLY. المنصة قيد التطوير حاليًا.',
    },
