      uk: 'Однопортальний рубіж стягнення плати в режимі «вільного потоку»: автомобілі проїжджають, не знижуючи швидкості, а система сама визначає, хто проїхав і скільки має сплатити. Рубіж працює для всіх транспортних засобів на швидкості до 250 км/год — удень і вночі, за будь-якої погоди. LIDAR класифікує машини за габаритами й кількістю осей, камери розпізнають номерні знаки, зокрема іноземні, зчитувачі приймають транспондери DSRC і RFID-мітки, а бек-офіс бере на себе білінг, платежі, роботу з клієнтами та контроль порушників.',
      zh: '自由流模式下的单门架收费站点：车辆无需减速即可通过，系统自动识别通行车辆及应缴费用。门架适用于所有车辆，车速最高250公里/小时，昼夜全天候运行。LIDAR按外廓尺寸和轴数对车辆分类，摄像机识别包括外国车牌在内的车牌，读取设备接收DSRC电子标签和RFID标签，后台系统负责计费、支付、客户服务及逃费稽查。',
      ar: 'نقطة تحصيل رسوم ببوابة واحدة في نمط التدفق الحر: تعبر المركبات دون أن تخفّف سرعتها، ويحدّد النظام بنفسه من عبر وكم يجب أن يدفع. تعمل البوابة لجميع المركبات بسرعات تصل إلى 250 كم/س، ليلًا ونهارًا وفي جميع الأحوال الجوية. يصنّف LIDAR المركبات حسب أبعادها وعدد محاورها، وتتعرّف الكاميرات على اللوحات بما فيها الأجنبية، وتستقبل أجهزة القراءة أجهزة DSRC وعلامات RFID، بينما يتولّى المكتب الخلفي الفوترة والمدفوعات وخدمة العملاء وملاحقة المخالفين.',
