      en: 'A platform for monitoring territories and infrastructure with drones — from setting the task to the finished report. The dispatcher plans the survey, selects areas of interest and assigns crews and equipment; a trained neural network processes the images, and an analyst confirms the findings. Every incident appears on the map with coordinates, photos and video; the platform builds orthophotos and 2D and 3D models, tracks flight hours and maintenance of the drone fleet and prepares reports automatically.',
