      zh: '利用无人机对区域和基础设施进行监测的平台——从任务设定到最终报告全流程覆盖。调度员规划航拍、选择关注区域并分配执行人员与设备；经过训练的神经网络处理影像，分析师确认识别结果。每个事件都会连同坐标、照片和视频标注在地图上；平台可生成正射影像、二维和三维模型，记录无人机机队的飞行时长与维护情况，并自动生成报告。',
