      uk: 'Цифрова біржа токенізованих реальних активів: зерно, золото й метали, нерухомість, сировина, дохідні інструменти та складські розписки. Торговий рушій, клірінг і Proof-of-Reserve працюють в єдиному регульованому контурі. Протокол STABILIA випускає токени лише під підтверджений резерв, а інтеграція з державними реєстрами, елеваторами, IoT і банками пов’язує кожен токен із реальним активом. Перший інструмент — $WGRAIN, токенізоване зерно на біржі в МФЦА (Казахстан) з ліцензією AFSA.',
