      ar: 'بورصة رقمية للأصول الحقيقية المرمّزة: الحبوب والذهب والمعادن والعقارات والسلع الأولية وأدوات الدخل وإيصالات المستودعات. يعمل محرّك التداول والمقاصّة وإثبات الاحتياطي ضمن نطاق تنظيمي موحّد. يُصدر بروتوكول STABILIA الرموز فقط مقابل احتياطي مؤكَّد، ويربط التكامل مع السجلات الحكومية وصوامع الحبوب وإنترنت الأشياء والبنوك كل رمز بأصل حقيقي. وأول أداة هي $WGRAIN — حبوب مرمّزة في بورصة ضمن مركز أستانا المالي الدولي (كازاخستان) بترخيص من AFSA.',
